){var w=World();var expected=JsonUtility.FromJson<MoveExpected>(File.ReadAllText(Dir+"move-expected.json"));if(!w.TrySelectedObjectInfo(out var name,out var id,out var position)||id!=expected.id||Vector2.Distance(new Vector2(position.x,position.z),new Vector2(expected.position.x,expected.position.z))>.01f)throw new Exception("Moved position did not persist in presentation");var marker=w.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name=="Runtime Object Selection"&&t.gameObject.activeInHierarchy);if(marker==null)throw new Exception("No active selection marker");File.AppendAllText(Dir+"move-check.txt",name+" | "+id+" | "+position+" | marker visible; paused; serialization passed\n");}else if(c.StartsWith("pick-runtime-")){var w=World();var suffix=c.Substring(13);var target=w.GetComponentsInChildren<LotRuntimeObject>().First(x=>x.Id.EndsWith(suffix));var camera=w.GetComponentInChildren<Camera>();if(camera==null)camera=(Camera)typeof(LotWorldController).GetField("_camera",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w);var renderer=target.GetComponentsInChildren<Renderer>().First(x=>x.enabled);var pixel=camera.WorldToScreenPoint(renderer.bounds.center);var size=new Vector2(camera.pixelWidth,camera.pixelHeight);var kind=w.BeginExistingObjectManipulationFromPanel(new Vector2(pixel.x,size.y-pixel.y),size);if(kind!=LotObjectSelectionKind.RuntimeObject)throw new Exception("Runtime ray selection failed: "+kind);if(!w.TrySelectedObjectInfo(out var name,out var id,out var pos)||id!=target.Id)throw new Exception("Wrong selected identity: "+id);var a=UnityEngine.Object.FindFirstObjectByType<CityForgeApp>();typeof(CityForgeApp).GetMethod("RemoveDocumentModal",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(a,null);typeof(CityForgeApp).GetField("_lotInspectorVisible",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(a,true);typeof(CityForgeApp).GetMethod("RefreshLotEditor",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(a,null);File.AppendAllText(Dir+"selection-check.txt",name+" | "+id+" | "+pos+"\n");}else if(c=="scroll-bottom"){var root=UnityEngine.Object.FindFirstObjectByType<CityForgeApp>().GetComponent<UnityEngine.UIElements.UIDocument>().rootVisualElement;var code=UnityEngine.UIElements.UQueryExtensions.Q<UnityEngine.UIElements.TextField>(root,"lot-script-source");var scroll=UnityEngine.UIElements.UQueryExtensions.Q<UnityEngine.UIElements.ScrollView>(root,"lot-script-scroll");scroll.verticalScroller.value=scroll.verticalScroller.highValue;File.WriteAllText(Dir+"scroll-check.txt","range="+scroll.verticalScroller.highValue+" value="+scroll.verticalScroller.value+" viewport="+scroll.contentViewport.layout+" content="+scroll.contentContainer.layout);}else if(c=="inspect-id"){var w=World();w.DeselectBuilding3D();typeof(LotWorldController).GetProperty("SelectedPropIndex").SetValue(w,0);typeof(LotWorldController).GetProperty("ActiveObjectSelection").SetValue(w,LotObjectSelectionKind.Prop);var app=UnityEngine.Object.FindFirstObjectByType<CityForgeApp>();var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(CityForgeApp).GetMethod("RemoveDocumentModal",flags).Invoke(app,null);typeof(CityForgeApp).GetField("_lotInspectorVisible",flags).SetValue(app,true);var cat=typeof(CityForgeApp).GetField("_lotEditorCategory",flags);cat.SetValue(app,Enum.Parse(cat.FieldType,"Boats"));typeof(CityForgeApp).GetMethod("RefreshLotEditor",flags).Invoke(app,null);}else if(c=="import-pane"){var app=UnityEngine.Object.FindFirstObjectByType<CityForgeApp>();typeof(CityForgeApp).GetMethod("OpenBehaviorScriptImport",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,new object[]{(Action<string>)(source=>typeof(CityForgeApp).GetMethod("OpenBehaviorScriptEditor",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,new object[]{source,null})),null});}else if(c=="trace"){var app=UnityEngine.Object.FindFirstObjectByType<CityForgeApp>();var root=(UnityEngine.UIElements.VisualElement)typeof(CityForgeApp).GetField("_root",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(app);root.RegisterCallback<UnityEngine.UIElements.PointerDownEvent>(e=>File.AppendAllText(Dir+"pointer-events.txt","DOWN "+e.position+" target="+e.target+" root="+root.worldBound+"\n"),UnityEngine.UIElements.TrickleDown.TrickleDown);root.RegisterCallback<UnityEngine.UIElements.PointerUpEvent>(e=>File.AppendAllText(Dir+"pointer-events.txt","UP "+e.position+" target="+e.target+"\n"),UnityEngine.UIElements.TrickleDown.TrickleDown);}else if(c=="script")typeof(CityForgeApp).GetMethod("OpenBehaviorScriptEditor",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(UnityEngine.Object.FindFirstObjectByType<CityForgeApp>(),new object[]{World().BehaviorScriptSource(World().LotBehaviors[0].InstanceId),World().LotBehaviors[0].InstanceId});else if(c=="objects")typeof(CityForgeApp).GetMethod("OpenLotScriptObjects",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(UnityEngine.Object.FindFirstObjectByType<CityForgeApp>(),new object[]{(Action)(()=>{})});else if(c=="save-current")World().SaveLot();else if(c=="timber-thumbnail")CharacterThumbnailBuilder.BuildLibrary(new[]{"axeman-labor-v01"},CharacterThumbnailBuilder.DirectoryPath,"QA/TimberLabor",false,id=>UnityEngine.Object.FindFirstObjectByType<DistrictWorldController>().CreateAxemanVisual(null,"Axeman Thumbnail").transform);else if(c.StartsWith("timber-"))UnityEngine.Object.FindFirstObjectByType<CityForgeApp>().TimberQa(c.Substring(7));else if(c=="lot-delete-ground-qa")UnityEngine.Object.FindFirstObjectByType<CityForgeApp>().CheckLotDeleteGroundQa();else if(c=="district-nine-user")UnityEngine.Object.FindFirstObjectByType<CityForgeApp>().OpenDistrictNinePlacementQa(false);else if(c=="district-nine")UnityEngine.Object.FindFirstObjectByType<CityForgeApp>().OpenDistrictNinePlacementQa();else if(c=="district")UnityEngine.Object.FindFirstObjectByType<CityForgeApp>().OpenDockDistrictQa();else if(c=="diagnose")Diagnose();else if(c=="follow"){var w=World();var camera=UnityEngine.Object.FindFirstObjectByType<DistrictWorldController>().WorldCamera;var boat=w.GetComponentsInChildren<Transform>().First(x=>x.name=="Prop — wooden-lumber-barge-v01");camera.transform.position=boat.position-camera.transform.forward*60;camera.orthographicSize=10;}else if(c=="ready"){var b=World().LotBehaviors[0];b.State.Loaded=12;foreach(var worker in b.State.Workers){worker.Phase="idle";worker.Carrying=false;}b.Enabled=true;}else if(c=="fresh-save"){var w=World();w.ResetBehavior(w.LotBehaviors[0].InstanceId);w.LotBehaviors[0].Enabled=true;File.WriteAllText(Dir+"saved-lot.txt",w.SaveLotAs("Lumber Mill Dock Operations v01"));}else if(c=="setup")Setup();else if(c=="focus")Focus();else if(c=="status")Status();else if(c=="reset")World().ResetBehavior(World().LotBehaviors[0].InstanceId);else if(c=="pause")World().ToggleBehavior(World().LotBehaviors[0].InstanceId);else if(c=="save"){var path=World().SaveLotAs("Lumber Mill Dock Operations v01");File.WriteAllText(Dir+"saved-lot.txt",path);}else if(c=="load"){World().LoadLot("lumber-mill-dock-operations-v01");Focus();}else if(c=="panel")typeof(CityForgeApp).GetMethod("OpenLotBehaviorsModal",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(UnityEngine.Object.FindFirstObjectByType<CityForgeApp>(),null);File.WriteAllText("/tmp/cityforge-dock-behavior-result.txt","OK "+c);}catch(Exception e){File.WriteAllText("/tmp/cityforge-dock-behavior-result.txt",e.ToString());Debug.LogException(e);}}
 static void Setup(){var w=World();var data=JsonUtility.FromJson<LotSaveData>(File.ReadAllText(Dir+"lumber-mill-before.json"));data.Name="Lumber Mill Dock Operations";data.LotWidthCells=4;data.LotDepthCells=3;data.LotSizeMeters=40;var boat=data.Props.First(x=>BoatCatalog.Find(x.PropId)!=null);boat.PositionX=13;boat.PositionZ=-5;boat.RotationQuarterTurns=0;data.Behaviors=new System.Collections.Generic.List<LotBehaviorInstance>();w.LoadRuntimeLot(data);w.DeselectBuilding3D();if(!w.AddCargoLoadingBehavior("lumber-loading-v01"))throw new Exception("Behavior attachment failed");var behavior=w.LotBehaviors[0];behavior.Pickup=new Vector3(9.5f,.06f,3);behavior.Dock=new Vector3(9.5f,.06f,-5);w.ResetBehavior(behavior.InstanceId);Focus();}
 static void Diagnose(){var w=World();var output=new System.Text.StringBuilder();foreach(var t in w.GetComponentsInChildren<Transform>(true).Where(x=>x.name.Contains("Loaded Lumber")||x.name.Contains("barge")))output.AppendLine(t.name+" pos="+t.position+" scale="+t.lossyScale);var boat=w.GetComponentsInChildren<Transform>().First(x=>x.name=="Prop — wooden-lumber-barge-v01");foreach(var mf in boat.GetComponentsInChildren<MeshFilter>()){var col=mf.gameObject.AddComponent<MeshCollider>();col.sharedMesh=mf.sharedMesh;for(int z=-3;z<=3;z++){var start=boat.TransformPoint(new Vector3(.7f,10,z));if(col.Raycast(new Ray(start,Vector3.down),out var hit,20))output.AppendLine("Deck z="+z+" y="+boat.InverseTransformPoint(hit.point).y);}UnityEngine.Object.Destroy(col);}File.WriteAllText(Dir+"visual-diagnostics.txt",output.ToString());}
